import{_ as t,o,c as d,ag as a}from"./chunks/framework.DUS-qonf.js";const p=JSON.parse('{"title":"Credential revocation","description":"","frontmatter":{},"headers":[],"relativePath":"security/revocation.md","filePath":"security/revocation.md","lastUpdated":1793762486000}'),s={name:"security/revocation.md"};function n(r,e,i,c,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="credential-revocation" tabindex="-1">Credential revocation <a class="header-anchor" href="#credential-revocation" aria-label="Permalink to &quot;Credential revocation&quot;">​</a></h1><p>What stops working when, for every kind of credential: admin sessions, API tokens and JWT sign-ins. Read it when you decide how to react to a leaked password or a departing user, or when you build a credential flow of your own.</p><h2 id="what-ends-when" tabindex="-1">What ends when <a class="header-anchor" href="#what-ends-when" aria-label="Permalink to &quot;What ends when&quot;">​</a></h2><p>The columns are the affected user&#39;s credentials. &quot;Signed out&quot; means the next request with that credential is anonymous (sessions) or refused with 401 (tokens, JWT).</p><table tabindex="0"><thead><tr><th>Event</th><th>Current session</th><th>Other sessions</th><th>API tokens (<code>rcms_…</code>)</th><th>JWT sign-ins (access + refresh)</th></tr></thead><tbody><tr><td>Sign out</td><td>ended</td><td>kept</td><td>kept</td><td>kept</td></tr><tr><td>Sign out everywhere (<code>logout-others</code>)</td><td>kept (new id)</td><td>signed out</td><td><strong>all revoked</strong></td><td><strong>all ended</strong></td></tr><tr><td>Password change</td><td>kept (new id)</td><td>signed out</td><td>all revoked (<code>revoke_tokens_on_password_change</code>)</td><td>all ended (always)</td></tr><tr><td>User disabled (<code>RbacService::set_user_active</code>)</td><td>ended</td><td>ended</td><td>all revoked</td><td>all ended</td></tr><tr><td>Email changed or password reset by an admin</td><td>signed out</td><td>signed out</td><td>all revoked</td><td>all ended</td></tr><tr><td>Password reset by link / invitation accepted</td><td>—</td><td>signed out</td><td>all revoked (<code>revoke_tokens_on_password_change</code>)</td><td>all ended</td></tr><tr><td>User deleted</td><td>ended</td><td>ended</td><td>deleted</td><td>deleted</td></tr><tr><td>One token revoked (<code>DELETE /api/v1/auth/token</code>)</td><td>—</td><td>—</td><td>that token</td><td>kept</td></tr><tr><td>JWT logout (<code>POST /api/v1/auth/jwt/logout</code>)</td><td>—</td><td>—</td><td>kept</td><td>that sign-in</td></tr><tr><td>A spent refresh token used again</td><td>—</td><td>—</td><td>kept</td><td>that sign-in</td></tr><tr><td><code>APP_KEY</code> rotated</td><td>ended</td><td>ended</td><td>kept</td><td>all ended</td></tr><tr><td>Roles or permissions changed</td><td>kept</td><td>kept</td><td>kept; new permissions apply on the next request</td><td>kept; new permissions apply on the next request</td></tr></tbody></table><p>With the default settings every row applies from the next request on every instance. The opt-in caches <a href="#several-instances">below</a> trade that for throughput on API instances.</p><p>Every row is covered by the framework&#39;s tests (<code>crates/rustcms-auth/tests/</code>: <code>auth_flow.rs</code>, <code>jwt.rs</code>, <code>recovery.rs</code>, <code>rbac.rs</code>, <code>instances.rs</code>).</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Account changes bump <code>users.auth_version</code> in the same transaction as the change. Sessions and JWT sign-ins store the version they were issued for, and every request checks it:</p><ul><li>A session of a <strong>disabled or deleted</strong> user is ended by the request that finds it.</li><li>A session whose version is <strong>old</strong> makes the request anonymous and is frozen: never renewed, no cookie sent, left to expire. It is not deleted at that point, because the same browser may be re-issuing it for the new version in a concurrent request (the browser that changed the password keeps its session, with a new id).</li><li>An access token (JWT) also checks that its sign-in is not revoked or expired; the credential change marks every sign-in of the user revoked.</li></ul><p><code>revoke_tokens_on_password_change</code> (default <code>true</code>) applies to API tokens only: JWT sign-ins always end, like sessions.</p><p>Resolved permissions are cached for at most <code>permission_cache_ttl_secs</code> (30), keyed by a counter (<code>auth_generations.rbac</code>) that every RBAC change advances in its own transaction, and by a counter of the instance that every change made through it advances.</p><h2 id="several-instances" tabindex="-1">Several instances <a class="header-anchor" href="#several-instances" aria-label="Permalink to &quot;Several instances&quot;">​</a></h2><p>By default, every request reads the RBAC counter, and a JWT&#39;s sign-in and user: a committed change applies on every instance from its next request. Two settings, off by default, let an instance reuse these reads for a short time so that a request does not pay for them every time (for example on <a href="./../digging-deeper/instances.html#api-mode">API mode</a> instances serving heavy traffic; <code>1000</code> is a reasonable value):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What is reused</th><th>A change made on another instance applies</th></tr></thead><tbody><tr><td><code>auth.permission_generation_cache_ms</code></td><td><code>0</code> (off)</td><td>the RBAC counter (<code>auth_generations.rbac</code>)</td><td>within that time: roles, permissions, and through them every guard</td></tr><tr><td><code>auth.jwt.session_cache_ms</code></td><td><code>0</code> (off)</td><td>a JWT&#39;s sign-in and user</td><td>within that time: sign-out, password change, user disabled or deleted</td></tr></tbody></table><p>When they are on:</p><ul><li><strong>On the instance that made the change</strong>, it applies on the next request: <code>RbacService</code>, the sign-out, refresh, password, reset and invitation endpoints forget this instance&#39;s cached reads. Credential functions called directly from your code (<code>credentials::logout_everywhere</code>, …) leave them to their time.</li><li>Sessions and API tokens are read on every request: their revocation is never delayed. Permissions they carry follow the RBAC counter above.</li><li>Leave them at <code>0</code> when a revocation must apply everywhere at once; each costs one statement per request.</li></ul><p>Session ids and refresh tokens are keyed from <code>APP_KEY</code> only, not from <code>APP_PREVIOUS_KEYS</code>: rotating the key ends them whatever the previous keys hold (<a href="./../operations/app-key.html">Rotating APP_KEY</a>).</p><p>Every admin response carries <code>x-rustcms-user: &lt;id&gt;</code> while signed in, so the panel can tell when the cookie changed accounts in another tab and never shows one user&#39;s page to another.</p><h2 id="races" tabindex="-1">Races <a class="header-anchor" href="#races" aria-label="Permalink to &quot;Races&quot;">​</a></h2><ul><li>Password changes, sign-out everywhere and token issuance re-check, inside a write transaction holding the user row, that the credentials verified earlier in the request are unchanged (password hash, <code>auth_version</code>, active). A token obtained with a password that is changed concurrently is refused, never issued after the revocation.</li><li>The permission cache is keyed by a generation advanced on every RBAC change: a lookup that started before a change cannot repopulate the cache with the old permissions.</li><li>JWT refresh tokens rotate under the locks of the user, the sign-in and the token, in that order (the same order as issuance and revocation). Two refreshes with one token: one wins, the other counts as a replay and ends the sign-in.</li><li>A request whose session was revoked can start a new one (CSRF, sign-in) in the same response.</li><li>A request already running when a credential is revoked finishes with the credentials checked when it started. Changes made through <code>RbacService</code> re-read the actor under lock and are refused (403) when the account&#39;s <code>auth_version</code> changed (password change, sign-out everywhere, admin reset), or the account was disabled or deleted. Revoking only one token, one JWT sign-in or one session does not change the account&#39;s version, so it does not stop an RBAC change that request already authenticated.</li></ul><h2 id="building-your-own-credential-flow" tabindex="-1">Building your own credential flow <a class="header-anchor" href="#building-your-own-credential-flow" aria-label="Permalink to &quot;Building your own credential flow&quot;">​</a></h2><p><code>rustcms::auth::credentials</code> holds the primitives the built-in endpoints use. Use them when you add a flow of your own (an SSO callback that must end other sessions, an admin tool that revokes a user&#39;s tokens):</p><table tabindex="0"><thead><tr><th>Function</th><th>Does</th></tr></thead><tbody><tr><td><code>lock_unchanged(&amp;txn, &amp;snapshot)</code></td><td>reloads the user under a row lock; 401 unless the password hash, <code>auth_version</code> and active flag still match <code>snapshot</code></td></tr><tr><td><code>revoke_all(&amp;txn, user_id, tokens)</code></td><td>bumps <code>auth_version</code>, ends every JWT sign-in and, with <code>tokens</code>, revokes every API token; returns the new version</td></tr><tr><td><code>revoke_tokens(&amp;txn, user_id)</code></td><td>revokes every API token of the user</td></tr><tr><td><code>change_password(db, &amp;snapshot, new_hash, revoke_api_tokens, &amp;audit)</code></td><td>sets the password and revokes the other credentials, in one transaction; returns the new version</td></tr><tr><td><code>logout_everywhere(db, &amp;snapshot, &amp;audit)</code></td><td>ends every session, sign-in and token; returns the new version</td></tr><tr><td><code>issue_token(db, &amp;snapshot, name, &amp;abilities, expires_at, &amp;request)</code></td><td>issues an API token, unless the credentials changed since they were verified</td></tr></tbody></table><p>Call <code>revoke_all</code> and <code>revoke_tokens</code> inside the transaction that changes the account, so the revocation commits or rolls back with it. After <code>change_password</code> or <code>logout_everywhere</code> in an admin request, keep the caller&#39;s session signed in with <code>session.restamp(new_version)</code> (the <code>Session</code> extractor); otherwise that request&#39;s own session is signed out too.</p><p>Revocations are recorded in the <a href="./../digging-deeper/audit-log.html">audit log</a>: <code>auth.password_changed</code>, <code>auth.signed_out_everywhere</code>, <code>token.revoked</code>, <code>token.created</code>, and the <code>user.*</code> entries of <code>RbacService</code>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a></li><li><a href="./../api/authentication.html">API authentication</a></li><li><a href="./authorization.html">Roles &amp; permissions</a></li><li><a href="./../operations/app-key.html">Rotating APP_KEY</a></li></ul>',28)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
